struct BuddyState { int path; int moving; bool active; };
struct BuddyInfo { BuddyState GetState() const { return state; } BuddyInfo() : soldier(0), progress(0) { state.moving = 0; state.active = false; state.path = 0; GetState(); } BuddyInfo(const BuddyInfo& o) : soldier(o.soldier), progress(o.progress) { state.moving = o.state.moving; state.active = o.state.active; state.path = o.state.path; } void* soldier; int progress; BuddyState state; };
